{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "상담사가 '관계가 끝나는 것과 저라는 사람이 끝나는 것이 같은 것처럼 느껴진다'고 반영한 부분에서, 내담자가 '확인하면 끝'이라고 표현한 핵심 두려움이 '사람들이 진짜 나를 알면 결국 떠날 것이다'라는 핵심 신념과 직접 연결됨. 연인이 '무슨 생각을 하는지 모르겠다'고 한 상황(상황 사례 1)이 이 신념을 촉발함."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "'관계가 끝나면 저라는 사람도 끝난다'는 표현은 관계가 단절되면 존재 자체가 무너진다는 단절/거절 도메인의 핵심 패턴을 보여줌. 어릴 적 형제 비교와 조건부 인정 경험(배경)이 관계 없이는 존재 가치가 없다는 인식을 형성함."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "'그 안에 뭔가 있다는 건 어렴풋이 아는데, 확인하면 끝'이라는 표현은 결함/수치심 스키마의 핵심—진짜 모습을 확인하면 사랑받을 수 없다는 공포—을 직접 드러냄. 밤에 과거 실수 순간이 떠오를 때 '그 모습이 진짜 나'라고 느끼는 상황(상황 사례 3)과 같은 구조."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 빈 느낌 안에 '뭔가 있을까 봐 걱정'한다고 말한 것은, 약점이나 진짜 감정을 드러내는 것을 끔찍한 일로 여기는 태도가 작동하고 있음을 보여줌. 어릴 적 힘들어하는 모습을 보이면 '남들 앞에서 그러지 말라'고 요구받은 경험이 이 태도의 원천."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/1"],
      "relevance": "'확인하면 끝'이라는 표현은 '부족하거나 힘든 모습을 보이면 사람들은 실망해서 떠날 것이다'라는 가정의 극단적 형태로, 연인의 말이 이 가정을 촉발한 상황(상황 사례 1)의 자동사고 '실망해서 헤어지자고 할 것이다'와 일치함."
    }
  ]
}

